"""Public blocked NMF similarity pilot with length and folio-distance matching."""

from collections import Counter, defaultdict, deque
from dataclasses import dataclass
import json
from pathlib import Path
import random
import re
from statistics import mean
import sys
import warnings

import numpy as np
import sklearn
from sklearn.decomposition import NMF
from sklearn.exceptions import ConvergenceWarning
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.preprocessing import normalize

from vs import corpus, ivtff


def tokenize(document):
    return document.split()


@dataclass
class Document:
    id: str
    folio: int
    section: str
    hand: str
    currier: str
    words: dict[str, list[str]]


def paragraph_words(page):
    return [
        word for line in page.lines if line.unit == 'P'
        for word in line.words if not ivtff.uncertain(word)
    ]


def collect_documents(plan):
    primary, _ = corpus.split_pages('practice', 'zl')
    alternative, _ = corpus.split_pages('practice', 'it')
    by_id = {page.id: page for page in alternative}
    documents = []
    for p in primary:
        q = by_id.get(p.id)
        match = re.fullmatch(r'f(\d+)[rv]\d*', p.id)
        if not q or not match or not p.hand or not p.section:
            continue
        if (p.hand, p.section, p.language) != (q.hand, q.section, q.language):
            continue
        words = {'zl': paragraph_words(p), 'it': paragraph_words(q)}
        if min(map(len, words.values())) < plan['eligible_min_paragraph_tokens_both_editions']:
            continue
        documents.append(Document(p.id, int(match[1]), p.section, p.hand, p.language, words))
    return documents


def block(doc, plan):
    return (doc.folio - 1) // plan['block_folios']


def compile_triads(documents, plan):
    triads = {'shared_section': [], 'same_currier': [], 'same_side': [], 'exact_distance': []}
    for anchor in documents:
        comparators = [
            doc for doc in documents
            if doc.section == anchor.section
            and 0 < abs(doc.folio - anchor.folio) <= plan['max_anchor_distance_folios']
        ]
        for positive in comparators:
            if positive.hand != anchor.hand:
                continue
            positive_offset = positive.folio - anchor.folio
            for negative in comparators:
                if negative.hand == anchor.hand or negative.folio == positive.folio:
                    continue
                negative_offset = negative.folio - anchor.folio
                imbalance = abs(abs(positive_offset) - abs(negative_offset))
                if imbalance > plan['max_distance_imbalance_folios']:
                    continue
                triple = anchor, positive, negative
                for edition in ('zl', 'it'):
                    lengths = [len(doc.words[edition]) for doc in triple]
                    if max(lengths) / min(lengths) > plan['max_largest_to_smallest_page_length_ratio_both_editions']:
                        break
                else:
                    triads['shared_section'].append(triple)
                    if anchor.currier in ('A', 'B') and anchor.currier == positive.currier == negative.currier:
                        triads['same_currier'].append(triple)
                    if positive_offset * negative_offset > 0:
                        triads['same_side'].append(triple)
                    if imbalance == 0:
                        triads['exact_distance'].append(triple)
    return triads


def synthetic(documents, prior, edition, seed, plan, planted):
    stream = random.Random(f'copy/{edition}/{seed}/{planted}')
    vocabulary, weights = zip(*sorted(prior.items()))
    total_words = sum(len(doc.words[edition]) for doc in documents)
    proposals = iter(stream.choices(vocabulary, weights=weights, k=total_words))
    memory = deque(maxlen=plan['copy_window_tokens'])
    previous_block = None
    output = {}
    for doc in documents:
        this_block = block(doc, plan)
        if this_block != previous_block:
            memory.clear()
        previous_block = this_block
        words = []
        for _ in doc.words[edition]:
            candidate = next(proposals)
            if memory and stream.random() < plan['copy_rate']:
                candidate = stream.choice(memory)
            memory.append(candidate)
            if planted and stream.random() < plan['positive_control_hand_token_rate']:
                candidate = f'planted_{doc.hand}_{stream.randrange(8)}'
            words.append(candidate)
        output[doc.id] = words
    return output


def documents_at_length(documents, words, size, seed):
    result = []
    for doc in documents:
        rng = random.Random(f'sample/{seed}/{doc.id}')
        result.append(' '.join(rng.sample(words[doc.id], size)))
    return result


def score_triads(similarity, docs, matched):
    index = {doc.id: position for position, doc in enumerate(docs)}
    by_folio = defaultdict(list)
    margins = defaultdict(list)
    for a, b, c in matched:
        anchor, positive, negative = (index[doc.id] for doc in (a, b, c))
        margin = float(similarity[anchor, positive] - similarity[anchor, negative])
        win = 0.5 if abs(margin) <= 1e-12 else float(margin > 0)
        by_folio[a.folio].append(win)
        margins[a.folio].append(margin)
    if not by_folio:
        return None
    return {
        'win_rate': mean(mean(wins) for wins in by_folio.values()),
        'margin': mean(mean(gaps) for gaps in margins.values()),
    }


def evaluate(train, test, matched, words, size, seed, plan):
    vectorizer = TfidfVectorizer(
        tokenizer=tokenize, token_pattern=None, lowercase=False, min_df=2, max_df=0.95
    )
    train_input = documents_at_length(train, words, size, seed)
    test_input = documents_at_length(test, words, size, seed)
    fitted = vectorizer.fit_transform(train_input)
    projected = vectorizer.transform(test_input)
    model = NMF(n_components=plan['topics'], init='nndsvda', solver='cd', max_iter=3000, random_state=1)
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter('always', ConvergenceWarning)
        model.fit(fitted)
        topic_weights = normalize(model.transform(projected))
    matrices = {
        'nmf': topic_weights @ topic_weights.T,
        'tfidf': (projected @ projected.T).toarray(),
    }
    metrics = {
        method: {group: score_triads(similarity, test, triples) for group, triples in matched.items()}
        for method, similarity in matrices.items()
    }
    return metrics, {
        'nonconvergence_warnings': sum(issubclass(entry.category, ConvergenceWarning) for entry in caught),
        'zero_test_vectors': int(sum(projected.getnnz(axis=1) == 0)),
    }


def summarise(entries):
    by_block = defaultdict(list)
    for block_id, metric in entries:
        if metric is not None:
            by_block[block_id].append(metric)
    rows = {
        str(block_id): {key: mean(row[key] for row in repeats) for key in ('win_rate', 'margin')}
        for block_id, repeats in sorted(by_block.items())
    }
    if not rows:
        return None
    return {
        **{key: mean(block[key] for block in rows.values()) for key in ('win_rate', 'margin')},
        'blocks': rows,
    }


def run(plan):
    documents = collect_documents(plan)
    groups = defaultdict(list)
    for doc in documents:
        groups[block(doc, plan)].append(doc)
    support = {}
    scores = defaultdict(list)
    diagnostics = Counter()
    for holdout, test in sorted(groups.items()):
        matched = compile_triads(test, plan)
        if not matched['shared_section']:
            continue
        train = [doc for doc in documents if abs(block(doc, plan) - holdout) > plan['embargo_blocks_each_side']]
        assert {doc.folio for doc in train}.isdisjoint(doc.folio for doc in test)
        support[str(holdout)] = {
            'train_pages': len(train),
            'test_pages': len(test),
            **{
                name: {
                    'triads': len(triples),
                    'anchor_folios': len({triad[0].folio for triad in triples}),
                    'all_folios': len({doc.folio for triad in triples for doc in triad}),
                    'sections': sorted({triad[0].section for triad in triples}),
                    'hands': sorted({doc.hand for triad in triples for doc in triad}),
                }
                for name, triples in matched.items()
            },
        }
        for edition in ('zl', 'it'):
            prior = Counter(word for doc in train for word in doc.words[edition])
            observed = {doc.id: doc.words[edition] for doc in train + test}
            for seed in plan['sampling_seeds']:
                pools = {
                    'observed': observed,
                    'copy': synthetic(sorted(train + test, key=lambda doc: doc.folio), prior, edition, seed, plan, False),
                    'planted_hand': synthetic(sorted(train + test, key=lambda doc: doc.folio), prior, edition, seed, plan, True),
                }
                for size in plan['samples_per_page']:
                    for scenario, words in pools.items():
                        metrics, counts = evaluate(train, test, matched, words, size, seed, plan)
                        diagnostics.update(counts)
                        for method, comparisons in metrics.items():
                            for group, metric in comparisons.items():
                                scores[edition, size, scenario, method, group].append((holdout, metric))
        print(f'Block {holdout} finished', flush=True)
    return {
        'plan': plan,
        'versions': {'sklearn': sklearn.__version__, 'numpy': np.__version__},
        'eligible_pages': len(documents),
        'support': support,
        'fit_diagnostics': dict(diagnostics),
        'scores': {'/'.join(map(str, key)): summarise(entries) for key, entries in scores.items()},
    }


def main():
    plan = json.loads(Path(sys.argv[1]).read_text())
    result = run(plan)
    Path(sys.argv[2]).write_text(json.dumps(result, indent=2) + '\n')
    print(result['fit_diagnostics'])
    for phase, metric in result['scores'].items():
        if '/40/' in phase and phase.endswith(('shared_section', 'same_currier')):
            print(phase, round(metric['win_rate'], 4) if metric else None)


if __name__ == '__main__':
    main()
